<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { cambiarEstadoTipoAfectacion, guardarTipoAfectacion, listarTiposAfectacion } from '../services/tiposAfectacion'
import type { TipoAfectacion, TipoAfectacionPayload } from '../interfaces/tiposAfectacion.interface'

type EstadoFiltro='todos'|'activo'|'inactivo'
const rows=ref<TipoAfectacion[]>([]),criterio=ref(''),estadoFiltro=ref<EstadoFiltro>('todos'),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive<TipoAfectacionPayload>({codigo:'',descripcion:''})
const message=(value:unknown)=>value instanceof Error?value.message:'No se pudo completar la operación.'
const filtered=computed(()=>{const search=criterio.value.trim().toLocaleLowerCase();return rows.value.filter(item=>(!search||item.codigo.toLocaleLowerCase().includes(search)||item.descripcion.toLocaleLowerCase().includes(search))&&(estadoFiltro.value==='todos'||item.estado===(estadoFiltro.value==='activo')))})

async function load(){loading.value=true;error.value='';try{rows.value=await listarTiposAfectacion()}catch(value){error.value=message(value)}finally{loading.value=false}}
function open(item?:TipoAfectacion){editing.value=item?.id??null;Object.assign(form,item?{codigo:item.codigo,descripcion:item.descripcion}:{codigo:'',descripcion:''});error.value='';modal.value=true}
function validate(){if(!form.codigo.trim())return 'El código es obligatorio.';if(form.codigo.trim().length>30)return 'El código admite como máximo 30 caracteres.';if(!form.descripcion.trim())return 'La descripción es obligatoria.';if(form.descripcion.trim().length>150)return 'La descripción admite como máximo 150 caracteres.';return ''}
async function save(){const issue=validate();if(issue)return void(error.value=issue);saving.value=true;error.value='';try{await guardarTipoAfectacion(editing.value,{codigo:form.codigo.trim().toUpperCase(),descripcion:form.descripcion.trim()});modal.value=false;success.value=`Tipo de afectación ${editing.value?'actualizado':'registrado'} correctamente.`;await load()}catch(value){error.value=message(value)}finally{saving.value=false}}
async function toggle(item:TipoAfectacion){const action=item.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} el tipo de afectación ${item.codigo}?`))return;try{const result=await cambiarEstadoTipoAfectacion(item.id);item.estado=result.estado;success.value=result.message??`Tipo de afectación ${item.estado?'activado':'desactivado'} correctamente.`}catch(value){error.value=message(value)}}
function clearFilters(){criterio.value='';estadoFiltro.value='todos'}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Tipos de afectación</nav><header class="hero"><div class="mark">TA</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Tipos de afectación</h1><p>Clasificación del impacto legal o tributario de los conceptos de planilla.</p></div><strong>{{filtered.length}} de {{rows.length}}</strong><button @click="open()">+ Nuevo tipo</button></header><aside class="help"><b>¿Para qué sirve?</b><span>Permite agrupar conceptos por su efecto en aportes sociales, retenciones fiscales, beneficios laborales y otros cálculos automáticos.</span></aside><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><label>Buscar por código o descripción<input v-model.trim="criterio" placeholder="Ej. APORTES"></label><label>Estado<select v-model="estadoFiltro"><option value="todos">Todos</option><option value="activo">Activos</option><option value="inactivo">Inactivos</option></select></label><button type="button" class="soft" @click="clearFilters">Limpiar</button></section><section class="table-card"><header><div><small>CLASIFICACIÓN DE CONCEPTOS</small><h2>Tipos registrados</h2></div></header><div v-if="loading" class="empty">Consultando tipos de afectación…</div><div v-else-if="!filtered.length" class="empty">No se encontraron tipos de afectación.</div><div v-else class="scroll"><table><thead><tr><th>Código</th><th>Descripción</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td><b>{{item.codigo}}</b></td><td>{{item.descripcion}}</td><td><span :class="item.estado?'active':'inactive'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button :class="item.estado?'disable':'enable'" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">TA</div><div><small>CLASIFICACIÓN DE CONCEPTOS</small><h2>{{editing?'Editar':'Registrar'}} tipo de afectación</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model="form.codigo" maxlength="30" placeholder="Ej. APORTES" @input="form.codigo=form.codigo.toUpperCase()"><small>{{form.codigo.length}} / 30 caracteres</small></label><label>Descripción *<input v-model="form.descripcion" maxlength="150" placeholder="Ej. Aportes y contribuciones sociales"><small>{{form.descripcion.length}} / 150 caracteres</small></label></div><div v-if="form.codigo||form.descripcion" class="preview"><small>VISTA PREVIA</small><p><span>Activo</span><b>{{form.codigo||'[CÓDIGO]'}}</b> — {{form.descripcion||'[DESCRIPCIÓN]'}}</p></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>

<style scoped>
.page{--accent:#b06a2d;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.62rem;font-weight:800}.hero small,.table-card small,.dialog small,.preview small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#fff3e8;font-size:.52rem}.hero button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.help{margin-top:10px;padding:12px 15px;display:flex;gap:9px;border-radius:8px;color:#356071;background:#eaf7fb;font-size:.56rem}.filters{margin-top:10px;padding:13px;display:flex;align-items:end;gap:6px;border-radius:9px;background:#fff}.filters label{min-width:220px;font-size:.52rem}.filters label:first-child{margin-right:auto;width:min(500px,100%)}.filters input,.filters select,.dialog input{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.soft{padding:9px 12px;border:0;border-radius:6px;color:#64727a!important;background:#edf1f3!important;font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;min-width:650px;border-collapse:collapse;font-size:.52rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}.active,.inactive{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.42rem}.active{color:#287154;background:#e6f7ee}.inactive{color:#667078;background:#edf1f3}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.46rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(720px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:8px;font-size:.5rem}.dialog label small{margin-top:5px;color:#7e8a90;font-weight:400}.grid{display:grid;grid-template-columns:1fr 2fr;gap:9px}.preview{margin-top:14px;padding:12px;border-radius:7px;background:#f7f8f9}.preview p{margin:6px 0 0;font-size:.55rem}.preview span{margin-right:8px;padding:4px 7px;border-radius:10px;color:#287154;background:#e6f7ee;font-size:.42rem}.dialog>footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:760px){.hero,.filters,.help{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%;min-width:0}.grid{grid-template-columns:1fr}.actions{min-width:140px}}
</style>
